buggy.nat_like_conversion_isnat:
import numpy as np

class NaTLike:
    year = month = day = float('nan')

def flag(x):
    try:
        return float(bool(np.isnat(x)))
    except Exception:
        return float('nan')

# 1) explicit-unit object-array conversion
try:
    arr_ns = np.asarray(NaTLike(), dtype=object).astype('datetime64[ns]')
    probe('explicit_unit_isnat', flag(arr_ns))
except Exception:
    probe('explicit_unit_isnat', float('nan'))

# 2) scalar np.datetime64 construction
try:
    sc = np.datetime64(NaTLike(), 'ns')
    probe('scalar_isnat', flag(sc))
except Exception:
    probe('scalar_isnat', float('nan'))

# 3) generic-unit (deprecated) conversion
try:
    arr_gen = np.asarray(NaTLike(), dtype=object).astype('datetime64')
    probe('generic_unit_isnat', flag(arr_gen))
except Exception:
    probe('generic_unit_isnat', float('nan'))

