import numpy as np

try:
    import pandas as pd
    _pd_src = "pandas"
except Exception:
    pd = None
    _pd_src = "shim"


class NaTLike:
    year = month = day = float("nan")


if pd is None:
    class _ShimNaT(object):
        year = month = day = float("nan")

    class _ShimModule(object):
        NaT = _ShimNaT()

    pd = _ShimModule()


def _isnat(value):
    try:
        return float(np.isnat(value))
    except Exception:
        return float("nan")


def _record(fn):
    try:
        return _isnat(fn())
    except Exception:
        return float("nan")


example_1 = "class NaTLike: year = month = day = float('nan')\nnp.asarray(NaTLike(), dtype=object).astype('datetime64[ns]')"
example_2 = "class NaTLike: year = month = day = float('nan')\nnp.datetime64(NaTLike(), 'ns')"
example_3 = "class NaTLike: year = month = day = float('nan')\nnp.asarray(NaTLike(), dtype=object).astype('datetime64')"
example_4 = "np.asarray(pd.NaT).astype('datetime64')"

probe(example_1, _record(lambda: np.asarray(NaTLike(), dtype=object).astype("datetime64[ns]")))
probe(example_2, _record(lambda: np.datetime64(NaTLike(), "ns")))
probe(example_3, _record(lambda: np.asarray(NaTLike(), dtype=object).astype("datetime64")))
probe(example_4, _record(lambda: np.asarray(pd.NaT).astype("datetime64")))

